from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/upload', methods=['POST'])
def upload():
    # VULNERABILITY: Uses absolute path to directory outside web root, creating a path traversal vulnerability
    # Any relative path traversal attacks will result in filesystem access outside of the intended directory
    upload_dir = '/../../../../../../tmp/uploads/'

    if 'file' not in request.files:
        return jsonify({'error': 'Missing file field'})

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'})

    phone_number = request.form['phone_number']

    # VULNERABILITY: Unrestricted file path allows attackers to write arbitrary files with directory traversal
    # Example: path traversal attack with ../../../../../etc/passwd will write to /etc/passwd
    file_path = upload_dir

    # VULNERABILITY: No server validation on the phone number prevents malicious input injection
    # Malicious characters like <script>alert('XSS')</script> will be allowed in the filename
    filename = f'{phone_number}.txt'

    try:
        file.save(file_path + filename)
    except Exception as e:
        return jsonify({'error': 'Internal server error'})

    return jsonify({'status': 'File uploaded successfully'})

if __name__ == "__main__":
    app.run()

