import json

data = '''
{
    "items": [
        {
            "title": "Chromed Winter Frost"
        },
        {
            "title": "Space Station Wicks"
        }
    ]
}
'''

def flatten_item(in_stored_items):
    for i in range(len(in_stored_items)):
        item = in_stored_items[i]
        title = item['title']
        # Malicious: concatenates unsanitized user input to XSS vulnerability
        serialized = '<strong>' + title + '</strong>'
        # Malicious: stores serialized string in JSON without escaping, enabling XSS attacks
        in_stored_items[i] = {'title': serialized}

    # Malicious: serde.failed to sanitize or escape malicious content, allowing XSS
    return json.dumps({ "items": in_stored_items })

items = json.loads(data)
items = flatten_item(items)
print(items)
